<script setup lang="ts">
import { onMounted, ref } from 'vue'
import Button from 'primevue/button'
import InputNumber from 'primevue/inputnumber'
import InputText from 'primevue/inputtext'
import Message from 'primevue/message'
import Select from 'primevue/select'
import Tag from 'primevue/tag'
import PageHeader from '~/components/design-system/PageHeader.vue'
import type { EnterpriseConfigSummary } from '~/types/enterpriseConfig'
definePageMeta({ middleware: 'auth' })
const api = useEnterpriseConfig(); const summary = ref<EnterpriseConfigSummary | null>(null); const loaded = ref(false); const error = ref<string | null>(null); const success = ref<string | null>(null); const saving = ref(false)
const nodeType = ref({ code: '', name: '', level_order: 10, description: '' })
const rule = ref({ parent_type_id: '', child_type_id: '' })
const node = ref({ node_type_id: '', parent_id: null as string | null, code: '', name: '', description: '' })
const versioned = ref({ kind: 'cost-structures' as 'cost-structures' | 'rate-books' | 'estimate-templates', code: '', name: '', version_number: 1, description: '' })
const mapping = ref({ target_system: '', source_dimension: '', source_value: '', target_value: '', version_number: 1 })
const kindOptions = [{ label: 'Cost breakdown structure', value: 'cost-structures' }, { label: 'Rate book', value: 'rate-books' }, { label: 'Estimate template', value: 'estimate-templates' }]
async function load() { summary.value = await api.summary(); loaded.value = true }
async function run(label: string, action: () => Promise<unknown>) { saving.value = true; error.value = null; success.value = null; try { await action(); success.value = `${label} created as audited configuration.`; await load() } catch (caught: unknown) { error.value = caught instanceof Error ? caught.message : 'Configuration failed' } finally { saving.value = false } }
async function createNodeType() { await run('Node type', () => api.createNodeType({ ...nodeType.value })) }
async function createRule() { await run('Hierarchy rule', () => api.createRule(rule.value.parent_type_id, rule.value.child_type_id)) }
async function createNode() { await run('Enterprise node', () => api.createNode({ ...node.value })) }
async function createVersioned() { const { kind, ...body } = versioned.value; await run('Draft configuration', () => api.createVersioned(kind, body)) }
async function createMapping() { await run('Reporting mapping', () => api.createMapping({ ...mapping.value })) }
onMounted(() => void load().catch((caught: unknown) => { error.value = caught instanceof Error ? caught.message : 'Load failed' }))
</script>
<template><div class="enterprise-config-page"><PageHeader title="Enterprise well-costing model" description="Configure the organization hierarchy and costing structures one audited record at a time. Versioned financial configuration remains Draft until separately published."><template #actions><Tag value="Bootstrap administrator" severity="info" /></template></PageHeader><Message severity="warn" :closable="false">No hierarchy, formula, approval, or reporting mapping is assumed. Create the structure that matches your enterprise; draft configuration does not change historical records.</Message><Message v-if="error" severity="error">{{ error }}</Message><Message v-if="success" severity="success">{{ success }}</Message><section class="enterprise-summary"><article><span>Node types</span><strong>{{ summary?.node_types.length ?? 0 }}</strong></article><article><span>Hierarchy nodes</span><strong>{{ summary?.nodes.length ?? 0 }}</strong></article><article><span>Cost structures</span><strong>{{ summary?.cost_structures.length ?? 0 }}</strong></article><article><span>Rate books</span><strong>{{ summary?.rate_books.length ?? 0 }}</strong></article><article><span>Templates</span><strong>{{ summary?.estimate_templates.length ?? 0 }}</strong></article><article><span>Mappings</span><strong>{{ summary?.reporting_mappings.length ?? 0 }}</strong></article></section><section v-if="loaded" class="enterprise-config-grid"><article><h2>1. Hierarchy level</h2><label>Code<InputText v-model="nodeType.code" fluid /></label><label>Name<InputText v-model="nodeType.name" fluid /></label><label>Order<InputNumber v-model="nodeType.level_order" :min="0" fluid /></label><Button label="Add node type" :loading="saving" @click="createNodeType" /></article><article><h2>2. Parent-child rule</h2><label>Parent type<Select v-model="rule.parent_type_id" :options="summary?.node_types ?? []" option-label="name" option-value="id" fluid /></label><label>Child type<Select v-model="rule.child_type_id" :options="summary?.node_types ?? []" option-label="name" option-value="id" fluid /></label><Button label="Add hierarchy rule" :loading="saving" @click="createRule" /></article><article><h2>3. Enterprise node</h2><label>Type<Select v-model="node.node_type_id" :options="summary?.node_types ?? []" option-label="name" option-value="id" fluid /></label><label>Parent<Select v-model="node.parent_id" :options="summary?.nodes ?? []" option-label="name" option-value="id" show-clear filter fluid /></label><label>Code<InputText v-model="node.code" fluid /></label><label>Name<InputText v-model="node.name" fluid /></label><Button label="Add enterprise node" :loading="saving" @click="createNode" /></article><article><h2>4. Costing configuration</h2><label>Configuration<Select v-model="versioned.kind" :options="kindOptions" option-label="label" option-value="value" fluid /></label><label>Code<InputText v-model="versioned.code" fluid /></label><label>Name<InputText v-model="versioned.name" fluid /></label><label>Version<InputNumber v-model="versioned.version_number" :min="1" fluid /></label><Button label="Create draft" :loading="saving" @click="createVersioned" /></article><article><h2>5. Reporting mapping</h2><label>Target system<InputText v-model="mapping.target_system" fluid /></label><label>Source dimension<InputText v-model="mapping.source_dimension" fluid /></label><label>Source value<InputText v-model="mapping.source_value" fluid /></label><label>Target value<InputText v-model="mapping.target_value" fluid /></label><Button label="Create draft mapping" :loading="saving" @click="createMapping" /></article><article><h2>Draft configuration register</h2><p v-for="item in [...(summary?.cost_structures ?? []), ...(summary?.rate_books ?? []), ...(summary?.estimate_templates ?? [])]" :key="item.id"><Tag :value="item.lifecycle_status" severity="warn" /> {{ item.code }} v{{ item.version_number }} · {{ item.name }}</p><p v-if="!summary?.cost_structures.length && !summary?.rate_books.length && !summary?.estimate_templates.length" class="muted-copy">No draft costing configuration yet.</p></article></section></div></template>
